mapper.select:
SELECT id, title, category, priority, pinned, due_date AS dueDate, completed, completed_at AS completedAt FROM todos
AND deleted_at IS NULL
AND title LIKE CONCAT('%', #{keyword}, '%')
AND category = #{category}
AND due_date >= #{from}
AND due_date <= #{to}
ORDER BY pinned DESC, due_date
DESC, id DESC ASC, id ASC
